"""Fixed per-run WebP preview cache. Never generated by playback requests."""
from pathlib import Path
import gzip,json,time,os,concurrent.futures,fcntl,multiprocessing
from PIL import Image,ImageDraw,ImageFont
from boundary_view import paint_overview
from placement_viewer import load_metadata,frames
import argparse
from preview_cache_state import CACHE_NAME, atomic_json, read_json, signature, preview_status
colors={'LUT':'#55baf2','FF':'#60dc91','DSP':'#ff9d47','BRAM':'#d68bff','URAM':'#ff6490','CARRY':'#f4d35e','MUX':'#b3a5ed','LUTRAM/SRL':'#44ddd0','OTHER':'#b9c3cf'}
W,H=900,1100
def render(src):
 target=root/(src.name+'.webp')
 if reuse and target.is_file() and target.stat().st_size:return target.name,target.stat().st_size
 x0,x1,y0,y1=meta['bounds']
 stretch=meta.get('display_x_stretch',4)
 scale=min((W-95)/(stretch*(x1-x0)),(H-40)/(y1-y0));sx=stretch*scale;sy=scale
 left=(W-(x1-x0)*sx)/2;bottom=H-20
 X=lambda x:round(left+(x-x0)*sx)
 Y=lambda y:round(bottom-(y-y0)*sy)
 im=Image.new('RGB',(W*2,H*2),'#111923');dr=ImageDraw.Draw(im)
 oldX,oldY=X,Y;X=lambda x:2*oldX(x);Y=lambda y:2*oldY(y)
 font=ImageFont.truetype('DejaVuSans.ttf',44);large=ImageFont.truetype('DejaVuSans.ttf',64)
 paint_overview(dr,meta,X,Y,font,large,unit=2)
 # Preserve source draw order, including overlap, with bounded per-type runs.
 prev=None;batch=[];small=[]
 def flush(t,coords):
  if not coords:return
  dr.point(coords,fill=colors[t])
  if len(types)<=5000:
   for x,y in coords:dr.rectangle((x,y,x+2,y+2),fill=colors[t])
  if t in ('DSP','BRAM','URAM'):
   for x,y in coords:dr.rectangle((x,y,x+1,y+1),fill=colors[t])
 with gzip.open(src,'rt') as f:
  for line in f:
   v=line.split(maxsplit=2)
   if len(v)<3:continue
   t=types.get(v[2].strip())
   if t not in colors:continue
   if t!=prev or len(batch)>=4096:flush(prev,batch);batch=[];prev=t
   batch.append((X(float(v[0])),Y(float(v[1]))))
   if len(types)<=5000:small.append(batch[-1])
 flush(prev,batch)
 if small and max(x for x,y in small)-min(x for x,y in small)<48 and max(y for x,y in small)-min(y for x,y in small)<48:
  cx=sum(x for x,y in small)/len(small);cy=sum(y for x,y in small)/len(small)
  dr.ellipse((cx-14,cy-14,cx+14,cy+14),outline='#75e5bf',width=3)
  dr.line((cx+14,cy,cx+38,cy),fill='#75e5bf',width=2)
  dr.text((cx+44,cy+8),f'{len(small)} cells',font=font,fill='#a9f6db',stroke_width=2,stroke_fill='#111923')
 im=im.resize((W,H),getattr(Image, 'Resampling', Image).LANCZOS)
 temp=target.with_suffix('.tmp');im.save(temp,format='WEBP',quality=75,method=4);temp.replace(target)
 return target.name,target.stat().st_size
def main():
    global root, reuse, types, meta
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run", type=Path, required=True)
    parser.add_argument("--traces", type=Path)
    parser.add_argument("--workers", type=int, default=4)
    args = parser.parse_args()
    if not 1 <= args.workers <= 4:
        parser.error("workers must be between 1 and 4")
    directory = args.traces or args.run / "placement"
    if args.traces is None and (directory / "visualization").is_dir():
        directory /= "visualization"
    directory = directory.resolve()
    sources = frames(directory)
    if not sources:
        parser.error("No coordinate frames found; no empty cache will be created")
    if preview_status(directory, sources)["ready"]:
        print("Preview cache already complete; reused without regeneration", flush=True)
        return
    root = directory / CACHE_NAME
    root.mkdir(exist_ok=True)
    lock = (root / "build.lock").open("a+")
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        parser.exit(2, "A preview generator is already active for this trace directory\n")
    previous = read_json(root / "build-status.json")
    current_signature = signature(sources)
    reuse = previous.get("source_signature") == current_signature
    record = {
        "state": "running", "phase": "preparing", "pid": os.getpid(),
        "started_at": time.time(), "updated_at": time.time(),
        "completed": 0, "total": len(sources), "workers": args.workers,
        "source_signature": current_signature, "traces": str(directory),
    }

    def update(**changes):
        record.update(changes, updated_at=time.time())
        atomic_json(root / "build-status.json", record)

    start = time.monotonic()
    update()
    try:
        types, meta = load_metadata(args.run / "config.json")
        update(phase="rendering")
        # Fork shares read-only metadata; the lock remains held until workers exit.
        with concurrent.futures.ProcessPoolExecutor(
            max_workers=args.workers, mp_context=multiprocessing.get_context("fork")
        ) as pool:
            results = []
            source_iter = iter(sources)
            pending = {pool.submit(render, source) for source in
                       [next(source_iter, None) for _ in range(args.workers)] if source is not None}
            while pending:
                done, pending = concurrent.futures.wait(
                    pending, return_when=concurrent.futures.FIRST_COMPLETED)
                for future in done:
                    item = future.result()
                    results.append(item)
                    update(completed=len(results), last_frame=item[0],
                           elapsed_seconds=time.monotonic() - start)
                    print(f"{len(results)}/{len(sources)} {item[0]}", flush=True)
                    source = next(source_iter, None)
                    if source is not None:
                        pending.add(pool.submit(render, source))
        if signature(frames(directory)) != current_signature:
            raise RuntimeError("Source frames changed during generation; refresh required")
        manifest = {
            "frames": [s.name for s in sources], "bytes": sum(size for _, size in results),
            "seconds": time.monotonic() - start, "size": [W, H], "quality": 75,
            "source_signature": current_signature,
        }
        atomic_json(root / "manifest.json", manifest)
        update(state="ready", phase="ready", elapsed_seconds=manifest["seconds"])
        print(f"Ready: {len(results)} frames, {manifest['seconds']:.3f} seconds", flush=True)
    except BaseException as error:
        update(state="failed", phase="failed", message=f"{type(error).__name__}: {error}",
               elapsed_seconds=time.monotonic() - start)
        raise
    finally:
        lock.close()


if __name__ == "__main__":
    main()
